INSERT INTO quiz_questions(kind,grade,subject,question,options_json,answer_idx,explain,active,is_custom,created_at,topic_id,chapter) VALUES
('study',3,'语文','《夜书所见》的作者是谁？','["刘禹锡","叶绍翁","杜牧","袁枚"]',1,'《夜书所见》是宋代诗人叶绍翁写的。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','“遥望洞庭山水翠，白银盘里一青螺”出自哪首诗？','["《山行》","《夜书所见》","《望洞庭》","《所见》"]',2,'这两句出自唐代刘禹锡的《望洞庭》，诗人把洞庭湖比作白银盘，把湖中的君山比作青螺。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','“霜叶红于二月花”是什么意思？','["霜打过的枫叶比二月的花还要红","二月的花被霜打红了","枫叶在二月里开花","霜把叶子变成了花"]',0,'“霜叶红于二月花”出自杜牧的《山行》，意思是深秋的枫叶比春天的花还要红，表达了诗人对秋天的喜爱。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','《所见》里，牧童忽然停下不唱歌，是想做什么？','["放牛回家","唱歌给黄牛听","在林子里捉迷藏","捕鸣蝉"]',3,'“意欲捕鸣蝉，忽然闭口立”：牧童想捉正在鸣叫的蝉，怕歌声惊跑它，就忽然停下不唱了。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','下面哪一句谚语说的是团结力量大？','["爱人若爱其身","人心齐，泰山移","不迁怒，不贰过","与人善言，暖于布帛"]',1,'“人心齐，泰山移”意思是大家心往一处想，再大的困难也能克服，说的是团结。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','“仁者爱人，有礼者敬人”出自哪本书？','["《论语》","《墨子》","《荀子》","《孟子》"]',3,'这句话出自《孟子》，意思是心怀仁爱的人爱别人，讲礼貌的人敬重别人。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','《不懂就要问》里的孙中山是个怎样的孩子？','["勤学好问","顽皮活泼","沉着冷静","严于律己"]',0,'孙中山小时候读书遇到不懂的地方就问先生，是个勤学好问的孩子。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','《总也倒不了的老屋》里的老屋有什么样的品质？','["顽皮活泼，想象力丰富","乐于助人，舍己为人","沉着冷静，临危不惧","严于律己，以身作则"]',1,'老屋一次次帮助小猫、老母鸡和小蜘蛛，最后自己倒下了，是乐于助人、舍己为人。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','《在牛肚子里旅行》里的青头是怎样的？','["顽皮活泼，想象力丰富","严于律己，以身作则","勤学好问","沉着冷静，临危不惧，用知识解救朋友"]',3,'青头被牛吞进肚子里也不慌张，冷静地想办法，用自己的知识救出了红头。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','下面哪个词是描写秋天的？','["骄阳似火","冰天雪地","春暖花开","秋高气爽"]',3,'“秋高气爽”是描写秋天的四字词；骄阳似火是夏天，冰天雪地是冬天，春暖花开是春天。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','下面哪个是 ABAB 式的词语？','["金灿灿","高高兴兴","雪白雪白","自言自语"]',2,'“雪白雪白”是 ABAB 式；金灿灿是 ABB 式，高高兴兴是 AABB 式，自言自语是 ABAC 式。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','下面哪个词里含有数字？','["披头散发","大惊小怪","七嘴八舌","面红耳赤"]',2,'“七嘴八舌”里有数字“七”；披头散发、面红耳赤是含身体部位的词语，大惊小怪是含反义词的词语。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','下面哪个是描写颜色的四字词语？','["五颜六色","七上八下","左思右想","东张西望"]',0,'“五颜六色”是描写颜色的词语；七上八下、左思右想、东张西望都是含有反义词的词语。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','“安静”的近义词是？','["摇摆","潮湿","宁静","飘动"]',2,'“安静”的近义词是“宁静”；摇摆是“摇晃”的近义词，潮湿是“湿润”的近义词，飘动是“飘扬”的近义词。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','选一选，量词搭配正确的是？','["一片秋风","一阵秋风","一只秋风","一个秋风"]',1,'风一阵一阵地吹，用“一阵秋风”；“一片”多用来搭配叶子，比如一片叶子。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','下面哪个动词搭配没有在课文里出现过？','["打招呼","看热闹","打羽毛球","睡大觉"]',2,'打招呼、看热闹、睡大觉都是课文里出现的动词搭配；“打羽毛球”没有在课文里出现过。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','《大青树下的小学》告诉我们什么道理？','["要经受考验，才能独自应对困难","要喜爱赞美洞庭湖的美景","各民族儿童友爱团结","要真心帮助别人"]',2,'《大青树下的小学》写了各民族儿童一起上学、一起玩耍，体现了各民族儿童友爱团结。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','《小狗学叫》告诉我们什么道理？','["要热爱秋天","只有经受考验，才能增强独自应对困难的能力","秋天是美丽丰收欢乐的","儿童天真活泼"]',1,'小狗在一次次尝试中学会了本领，告诉我们只有经受考验，才能增强独自应对困难的能力。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','《大青树下的小学》是按什么顺序来写的？','["上学路上、来到学校、上课、下课的时间顺序","先写下课，再写上课","按从远到近的空间顺序","按事情发展的顺序"]',0,'课文按“上学路上、来到学校、上课、下课”的时间顺序，写了边疆小学一天的生活。',1,0,1794199164,NULL,'通用复习'),
('study',3,'语文','反问句改陈述句：“这样糊里糊涂地背，有什么用呢？”改成陈述句是？','["这样糊里糊涂地背，有什么用？","这样糊里糊涂地背，没有用。","这样糊里糊涂地背，有用吗？","这样糊里糊涂地背，没有用呢？"]',1,'反问句“这样糊里糊涂地背，有什么用呢？”改成陈述句是“这样糊里糊涂地背，没有用。”',1,0,1794199164,NULL,'通用复习');
